import os
import re
from pathlib import Path
from typing import Dict, Any

def task_func(dir_path: str, predicates: list) -> dict:
    """
    Evaluates each item (files and directories) in a given directory against specified conditions.

    Parameters:
    dir_path (str): Path to the directory to evaluate
    predicates (list): List of conditions to check. Each condition can be:
        - A string pattern (matches filename against regex)
        - A callable that takes filename and returns boolean

    Returns:
    dict: Dictionary with directory items as keys and results of condition checks as values

    Raises:
    ValueError: If no valid predicates are provided
    FileNotFoundError: If the specified directory does not exist or is not a directory
    """
    # Validate directory path
    if not os.path.exists(dir_path) or not os.path.isdir(dir_path):
        raise FileNotFoundError(f"The directory '{dir_path}' does not exist or is not a directory.")

    # Process and deduplicate predicates
    valid_predicates = []
    seen = set()

    for pred in predicates:
        if pred is None:
            continue

        if callable(pred):
            # For callables, use their name as identifier
            pred_id = f"callable_{id(pred)}"
        elif isinstance(pred, str):
            # For strings, compile and use the pattern as identifier
            try:
                compiled = re.compile(pred)
                pred_id = f"regex_{pred}"
            except re.error:
                continue  # Skip invalid regex patterns
        else:
            continue  # Skip unsupported types

        if pred_id not in seen:
            seen.add(pred_id)
            valid_predicates.append(pred)

    if not valid_predicates:
        raise ValueError("No valid predicates are provided.")

    # Evaluate each item in the directory
    result = {}
    try:
        items = os.listdir(dir_path)
    except PermissionError:
        raise FileNotFoundError(f"Permission denied to access directory '{dir_path}'.")

    for item in items:
        # Evaluate against all predicates
        matches = []
        for pred in valid_predicates:
            if callable(pred):
                try:
                    matches.append(pred(item))
                except Exception:
                    matches.append(False)
            elif isinstance(pred, str):
                try:
                    matches.append(bool(re.search(pred, item)))
                except Exception:
                    matches.append(False)

        # Store result: True if all predicates match, False otherwise
        result[item] = all(matches) if matches else False

    return result
